    actual = verify_artifact()
    if card.get('artifact') and actual['status'] != 'PASS':
        raise ValueError('Refusing to publish an unverified or missing download')
    checks = gates(card)
    ready = submission_ready(card)
    if card.get('submission_ready') is not ready:
        raise ValueError('Run-card readiness contradicts the fail-closed shared policy')
    if ready:
        raise ValueError('This research-only portal cannot promote candidates; use the separate selector workflow')
